#!/usr/bin/env bash
# ============================================================================
# FIRONOVA — Installeur analytics enrichi (idempotent)
# Ajoute GET /admin/analytics/enhanced (AOV, conversion, comparaison, seuil taxe)
# À exécuter depuis /app :  bash install_analytics_enhanced.sh
# ============================================================================
set -euo pipefail
cd "$(dirname "$0")"
SERVER="backend/server.py"; [ -f "$SERVER" ] || SERVER="server.py"
[ -f "$SERVER" ] || { echo "server.py introuvable"; exit 1; }
cp "$SERVER" "${SERVER}.bak-analytics-$(date +%Y%m%d-%H%M%S)"
echo "Backup créé."
export ANA_B64=''
python3 - "$SERVER" << 'PYEOF'
import sys, re, ast, base64, os
path = sys.argv[1]; src = open(path).read()
BLOCK = base64.b64decode(os.environ["ANA_B64"]).decode()
wrapped = "\n\n# ===== FIRONOVA_ANALYTICS_ENHANCED_START =====\n" + BLOCK + "\n# ===== FIRONOVA_ANALYTICS_ENHANCED_END =====\n"
if "FIRONOVA_ANALYTICS_ENHANCED_START" in src:
    src = re.sub(r"# ===== FIRONOVA_ANALYTICS_ENHANCED_START =====.*?# ===== FIRONOVA_ANALYTICS_ENHANCED_END =====\n", wrapped.strip()+"\n", src, flags=re.DOTALL); print("  bloc analytics remplace")
else:
    src = src.replace("app.include_router(api)", wrapped + "\napp.include_router(api)", 1); print("  bloc analytics injecte")
ast.parse(src); open(path,"w").write(src); print("OK - AST valide.")
PYEOF
echo "Termine. Redemarre le backend."
